pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0) && uint160(actor) > 100);

        // grant admin rights to the fuzzed actor (isAdmin is at slot 0, mapping key actor)
        vm.store(address(c), keccak256(abi.encode(actor, uint256(0))), bytes32(uint256(1)));

        // c has not deployed anything before, so the oracle is created at CREATE(c, nonce=0)
        vm.prank(actor);
        c.newEmergencyOracle(description);

        // predict CREATE address: rlp([caller, 0]) = d6 94 <addr> 80
        bytes memory rlp = abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(c), bytes1(0x80));
        address oracleAddr = address(uint160(uint256(keccak256(rlp))));

        // the freshly deployed oracle must be owned by the caller, not address(0)
        assertTrue(IEmergencyOracle(oracleAddr).owner() == actor);
    }
}

