pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));

        // c will create the EmergencyOracle with CREATE during the call;
        // its address is deterministic from c's address and its current nonce.
        address predicted = computeCreateAddress(address(c), 0);

        vm.prank(actor);
        try c.newEmergencyOracle(description) {
            // property: the oracle created by c must have a NONZERO owner.
            // In the reference, the owner is the caller (nonzero); the mutant
            // wires address(0) as the owner, so owner() reads back as zero.
            assertTrue(
                IEmergencyOracle(predicted).owner() != address(0),
                "created emergency oracle must not be owned by address(0)"
            );
        } catch {
            // no oracle was created; nothing to check
            assertTrue(true);
        }
    }
}

