pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    uint256 nextNonce = 1; // c's first CREATE happens after its own deployment (nonce 1)

    function setUp() public { c = new C(); }

    function _rlpAddr(address a) internal pure returns (bytes memory) {
        return abi.encodePacked(bytes1(0x94), bytes20(a));
    }

    function _rlpNonce(uint256 n) internal pure returns (bytes memory) {
        if (n == 0) return hex"80";
        if (n <= 0x7f) return abi.encodePacked(bytes1(uint8(uint8(n))));
        uint256 len;
        uint256 tmp = n;
        while (tmp > 0) { len++; tmp >>= 8; }
        bytes memory b = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            b[len - 1 - i] = bytes1(uint8(n >> (8 * i)));
        }
        return abi.encodePacked(bytes1(uint8(0x80 + len)), b);
    }

    function _predict(address deployer, uint256 nonce) internal pure returns (address) {
        bytes memory payload = abi.encodePacked(hex"d6", _rlpAddr(deployer), _rlpNonce(nonce));
        bytes1 header = bytes1(uint8(0xc0 + payload.length));
        return address(uint160(uint256(keccak256(abi.encodePacked(header, payload)))));
    }

    function testFuzz_property(address actor, string calldata description) public {
        // Wide admissible domain: any nonzero actor with any nonempty description.
        vm.assume(actor != address(0));
        vm.assume(bytes(description).length > 0);

        // Predict where c's factory will place the new oracle via CREATE.
        address predicted = _predict(address(c), nextNonce);
        nextNonce++;

        vm.prank(actor);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever the factory call succeeds, the freshly created
        // oracle must NOT be owned by the zero address (P sets owner = msg.sender,
        // a nonzero admissible actor; M sets owner = address(0)).
        assertTrue(!ok || IEmergencyOracle(predicted).owner() != address(0));
    }
}

