pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function turnOnOracle() external;
    function setAssetPrice(uint256) external;
    function getAssetPrice() external view returns (uint256);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description, uint256 price) public {
        vm.assume(actor != address(0));

        // create the oracle from an admin actor
        bool created;
        vm.prank(actor);
        try c.newEmergencyOracle(description) { created = true; } catch { created = false; }

        // c's first deployment from nonce 1 (constructor deploys nothing, single successful create)
        address oracle = address(
            uint160(uint256(keccak256(abi.encodePacked(hex"d694", uint160(address(c)), hex"01"))))
        );

        // rule: the creator can operate the oracle it just created
        bool on = false;
        if (created) {
            vm.prank(actor);
            try IEmergencyOracle(oracle).turnOnOracle() { on = true; } catch { on = false; }
        }

        bool priceOk = false;
        if (created) {
            vm.prank(actor);
            try IEmergencyOracle(oracle).setAssetPrice(price) {
                try IEmergencyOracle(oracle).getAssetPrice() returns (uint256 p) {
                    priceOk = (p == price);
                } catch { priceOk = false; }
            } catch { priceOk = false; }
        }

        assertTrue(created && on && priceOk);
    }
}

