pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Compute the CREATE address of a contract deployed by `sender` at nonce n (n < 128).
    function _createAddress(address sender, uint8 n) internal pure returns (address) {
        bytes memory rlp;
        if (n == 0) {
            rlp = abi.encodePacked(hex"d694", sender, hex"80");
        } else {
            rlp = abi.encodePacked(hex"d694", sender, bytes1(n));
        }
        return address(uint160(uint256(keccak256(rlp))));
    }

    // General rule: for any description, a successful newEmergencyOracle call by a caller
    // deploys an EmergencyOracle (at the caller's next CREATE address) whose owner() is
    // that caller — a live, non-zero owner. The mutant owns the oracle by address(0).
    function testFuzz_property(string calldata description) public {
        // the caller of newEmergencyOracle is the test contract (deployer of c),
        // the natural admin; the description space stays fully fuzzed.
        address caller = address(this);

        uint8 nonce = 0; // c has not deployed anything yet; increment on each successful deploy
        address predicted = _createAddress(address(c), nonce);

        vm.prank(caller);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // read the freshly deployed oracle's owner() through its public surface
            (bool callOk, bytes memory ret) = predicted.call(abi.encodeWithSignature("owner()"));
            assertTrue(callOk && ret.length == 32 && abi.decode(ret, (address)) == caller);
        } else {
            // call was not admissible (caller not admin): both versions revert identically
            assertTrue(true);
        }
    }
}

