pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        c.isAdmin(actor);
        // make actor an admin
        vm.startPrank(actor);
        // no setter for isAdmin exists publicly other than direct; use prank as admin via constructor? fallback:
        vm.stopPrank();

        // make actor admin by pranking the contract itself is not possible; instead use vm.prank on a
        // pre-set admin: we set admin through the only writable path — there is none, so use vm.store-free
        // approach: deploy C and set isAdmin via a prank as c itself cannot. Use vm.prank(actor) after
        // flipping via... none. Instead we treat actor as admin by calling with a prank after writing
        // through the public mapping setter generated for `public bool isAdmin`:
        vm.prank(actor);
        c.isAdmin(actor);

        vm.prank(address(c));
        // generated setter: isAdmin(address,bool)
        // (called above incorrectly; correct call below)

        vm.prank(address(c));
        (bool okSet, ) = address(c).call(
            abi.encodeWithSignature("isAdmin(address,bool)", actor, true)
        );
        assertTrue(okSet);

        vm.recordLogs();
        vm.prank(actor);
        c.newEmergencyOracle(description);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        bool found = false;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].emitter == address(c)) {
                if (logs[i].topics[0] == keccak256("NewEmergencyOracle(address,address)")) {
                    found = true;
                }
            }
        }
        assertTrue(found, "NewEmergencyOracle event must be emitted for every successful call");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testNonAdminCannotCreateOracle(address anyCaller, string calldata description) external {
        require(anyCaller != address(this));
        // Simulate a call from an arbitrary (non-admin) account context is not possible directly,
        // so instead check from this contract's own perspective: unless this contract was made admin,
        // the call must revert on P.
        bool isAdmin = c.isAdmin(address(this));
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.newEmergencyOracle.selector, description)
        );
        assert(success == isAdmin);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(bool isAdminFlag, string calldata description) external {
        require(isAdminFlag == true, "admin flag must be true");
        c.isAdmin(address(this), true);
        c.newEmergencyOracle(description);
        assert(c.isAdmin(address(this)) == isAdminFlag);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool isAdminCaller = c.isAdmin(address(this));
        bool reverted;
        try c.newEmergencyOracle("test") { reverted = false; } catch { reverted = true; }
        assert(isAdminCaller ? !reverted : reverted);
    }
    receive() external payable {}
}

